<template>
  <figure ref="figure" class="view-journey-demo index-ignore">
    <div ref="scroll" class="view-journey-scroll" :style="{ '--journey-morph': morphProgress }">
      <div class="view-journey-sticky">
        <button v-if="requiresActivation" class="view-journey-activate" type="button" @click="frameActivated = true">Play the live comparison</button>
        <div class="view-journey-stage" :class="[focus ? `is-focusing-${focus}` : '', { 'is-paired': morphProgress > .72 }]" :style="morphStageStyle">
      <div class="view-journey-lead"><slot name="lead"></slot></div>
      <section class="view-journey-article" :class="{ 'is-focused': focus === 'article', 'is-receding': focus === 'exhibition' }" @click="toggleFocus('article')">
        <header>
          <span>Article</span>
          <button type="button" :aria-label="focus === 'article' ? 'Show both presentations' : 'Enlarge the article'" :aria-pressed="focus === 'article'" @click.stop="toggleFocus('article')"><i aria-hidden="true"></i></button>
        </header>
        <div ref="articleStage" class="view-journey-frame">
          <iframe
            v-if="mountedFrames"
            ref="articleFrame"
            :src="articleUrl"
            title="A View moving through its article presentation"
            :style="articleFrameStyle"
            tabindex="-1"
            @load="sendPlaybackState"
          ></iframe>
          <div v-else class="view-journey-placeholder" aria-hidden="true"><i></i><i></i><i></i></div>
        </div>
      </section>
      <div class="view-journey-link" aria-hidden="true"><i></i><span>Same place</span><i></i></div>
      <section class="view-journey-exhibition" :class="{ 'is-focused': focus === 'exhibition', 'is-receding': focus === 'article' }" @click="toggleFocus('exhibition')">
        <header>
          <span>Exhibition</span>
          <button type="button" :aria-label="focus === 'exhibition' ? 'Show both presentations' : 'Enlarge the exhibition'" :aria-pressed="focus === 'exhibition'" @click.stop="toggleFocus('exhibition')"><i aria-hidden="true"></i></button>
        </header>
        <div ref="exhibitionStage" class="view-journey-frame">
          <iframe
            v-if="mountedFrames"
            ref="exhibitionFrame"
            :src="exhibitionUrl"
            title="The same View moving through its exhibition presentation"
            :style="exhibitionFrameStyle"
            tabindex="-1"
            allow="autoplay 'none'; fullscreen"
            @load="sendPlaybackState"
          ></iframe>
          <div v-else class="view-journey-placeholder" aria-hidden="true"><i></i><i></i><i></i></div>
        </div>
          </section>
        </div>
        <button v-if="mountedFrames" class="view-journey-transport view-journey-stage-transport" type="button" :aria-label="paused ? 'Continue demonstration' : 'Pause demonstration'" @click="paused = !paused">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
        </button>
      </div>
    </div>
    <figcaption>
      <p>Article and exhibition share one saved position. Each passage leads to its room or original work.</p>
      <div class="view-journey-actions">
        <a :href="articleOpenUrl" target="_blank" rel="noopener">Open article <span aria-hidden="true">↗</span></a>
        <a :href="exhibitionOpenUrl" target="_blank" rel="noopener">Open exhibition <span aria-hidden="true">↗</span></a>
      </div>
    </figcaption>
  </figure>
</template>

<script>
const BASE = { width: 1440, height: 900 };

export default {
  name: 'ViewPresentationJourneyDemo',
  props: { shareId: { type: String, default: 'PNZPdB__yBeyYjkF' }, enabled: { type: Boolean, default: true } },
  data: () => ({ visible: false, playbackVisible: false, pageVisible: true, frameKey: 0, articleScale: 1, exhibitionScale: 1, focus: '', paused: false, morphProgress: 0, constrainedDevice: false, frameActivated: false }),
  computed: {
    requiresActivation() { return this.constrainedDevice && !this.frameActivated; },
    mountedFrames() { return this.enabled && this.visible && this.pageVisible && !this.requiresActivation; },
    channel() { return `view-journey-${this.frameKey}`; },
    routeBase() { return `${window.location.pathname}#/view/${this.shareId}`; },
    articleUrl() { return `${this.routeBase}?presentation=article&embedded=1&preview=1&galleryFrame=1&showcase=articleJourney&showcaseChannel=${this.channel}`; },
    exhibitionUrl() { return `${this.routeBase}?presentation=museum&galleryFrame=1&showcase=linkedJourney&showcaseChannel=${this.channel}`; },
    articleOpenUrl() { return `${this.routeBase}?presentation=article&temporaryPresentation=1`; },
    exhibitionOpenUrl() { return `${this.routeBase}?presentation=museum&temporaryPresentation=1`; },
    articleFrameStyle() { return this.frameStyle(this.articleScale); },
    exhibitionFrameStyle() { return this.frameStyle(this.exhibitionScale); },
    effectivePaused() { return this.paused || !this.playbackVisible || !this.pageVisible; },
    morphStageStyle() {
      if (window.matchMedia('(max-width: 760px)').matches) return { gridTemplateColumns: 'minmax(0,1fr)' };
      if (this.focus === 'article' && this.morphProgress > .72) return { gridTemplateColumns: 'minmax(0,1.3fr) 3.5rem minmax(0,.7fr)' };
      if (this.focus === 'exhibition' && this.morphProgress > .72) return { gridTemplateColumns: 'minmax(0,.7fr) 3.5rem minmax(0,1.3fr)' };
      return { gridTemplateColumns: `minmax(0,${0.62 + 0.38 * this.morphProgress}fr) ${3.5 * this.morphProgress}rem minmax(0,${1.38 - 0.38 * this.morphProgress}fr)` };
    },
  },
  mounted() {
    this.constrainedDevice = window.matchMedia('(max-width: 760px)').matches || (Number(navigator.deviceMemory || 0) > 0 && Number(navigator.deviceMemory) <= 4) || (Number(navigator.hardwareConcurrency || 0) > 0 && Number(navigator.hardwareConcurrency) <= 4);
    this.frameActivated = !this.constrainedDevice;
    this._resize = new ResizeObserver(this.measure);
    this._resize.observe(this.$refs.articleStage);
    this._resize.observe(this.$refs.exhibitionStage);
    this._observer = new IntersectionObserver(entries => {
      if (!entries.some(entry => entry.isIntersecting)) return;
      this.visible = true;
      this._observer.disconnect();
      this._observer = null;
      this.$nextTick(this.measure);
    }, { rootMargin: '240px 0px' });
    if (this.enabled) this._observer.observe(this.$refs.figure);
    this._playbackObserver = new IntersectionObserver(entries => {
      this.playbackVisible = Boolean(entries[0]?.isIntersecting && entries[0].intersectionRatio >= .25);
    }, { threshold: [0, .25] });
    this._playbackObserver.observe(this.$refs.figure);
    this._visibility = () => { this.pageVisible = !document.hidden; };
    this._visibility();
    document.addEventListener('visibilitychange', this._visibility);
    this._onScroll = () => {
      if (this._morphFrame) return;
      this._morphFrame = requestAnimationFrame(() => { this._morphFrame = 0; this.syncMorph(); });
    };
    window.addEventListener('scroll', this._onScroll, { passive: true });
    window.addEventListener('resize', this._onScroll, { passive: true });
    window.addEventListener('message', this.forwardPosition);
    this.$nextTick(this.syncMorph);
  },
  beforeUnmount() {
    this._observer?.disconnect();
    this._playbackObserver?.disconnect();
    this._resize?.disconnect();
    cancelAnimationFrame(this._morphFrame);
    document.removeEventListener('visibilitychange', this._visibility);
    window.removeEventListener('scroll', this._onScroll);
    window.removeEventListener('resize', this._onScroll);
    window.removeEventListener('message', this.forwardPosition);
  },
  watch: {
    enabled(value) {
      if (!value || this.visible) return;
      this._observer?.observe(this.$refs.figure);
    },
    paused() { this.sendPlaybackState(); },
    playbackVisible() { this.sendPlaybackState(); },
    pageVisible() { this.sendPlaybackState(); },
  },
  methods: {
    frameStyle(scale) {
      return { width: `${BASE.width}px`, height: `${BASE.height}px`, transform: `scale(${scale})` };
    },
    syncMorph() {
      const element = this.$refs.scroll;
      if (!element || window.matchMedia('(max-width: 760px)').matches) { this.morphProgress = 1; return; }
      const rect = element.getBoundingClientRect();
      const stickyHeight = Math.min(window.innerHeight * .66, 660);
      const travel = Math.max(1, element.offsetHeight - stickyHeight);
      this.morphProgress = Math.max(0, Math.min(1, -rect.top / travel));
    },
    measure() {
      this.articleScale = Math.min(1, (this.$refs.articleStage?.clientWidth || BASE.width) / BASE.width);
      this.exhibitionScale = Math.min(1, (this.$refs.exhibitionStage?.clientWidth || BASE.width) / BASE.width);
    },
    forwardPosition(event) {
      if (event.origin !== window.location.origin || event.source !== this.$refs.articleFrame?.contentWindow) return;
      const message = event.data;
      if (message?.type !== 'view-article-showcase-position' || message.channel !== this.channel) return;
      this.$refs.exhibitionFrame?.contentWindow?.postMessage({
        type: 'view-exhibition-showcase-position',
        channel: this.channel,
        position: message.position,
      }, window.location.origin);
    },
    sendPlaybackState() {
      const message = { type: 'view-gallery-showcase-playback', channel: this.channel, paused: this.effectivePaused };
      this.$refs.articleFrame?.contentWindow?.postMessage(message, window.location.origin);
      this.$refs.exhibitionFrame?.contentWindow?.postMessage(message, window.location.origin);
    },
    restart() { this.frameKey += 1; },
    toggleFocus(kind) {
      if (this.morphProgress <= .72) return;
      this.focus = this.focus === kind ? '' : kind;
      this.$nextTick(this.measure);
    },
  },
};
</script>

